const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/documents',
  qs: {
    view: 'SOME_STRING_VALUE',
    sort: 'SOME_STRING_VALUE',
    'filters[id]': 'SOME_ARRAY_VALUE',
    'filters[created_by_id]': 'SOME_ARRAY_VALUE',
    'filters[created_at]': 'SOME_STRING_VALUE',
    'filters[updated_at]': 'SOME_STRING_VALUE',
    'filters[document_type]': 'SOME_STRING_VALUE',
    'filters[file_type]': ['pdf', 'txt'],
    'filters[is_in_recycle_bin]': 'SOME_BOOLEAN_VALUE',
    'filters[search]': 'SOME_STRING_VALUE',
    'filters[folder_id]': '26',
    'filters[private]': 'SOME_BOOLEAN_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/documents?view=SOME_STRING_VALUE&sort=SOME_STRING_VALUE&filters%5Bid%5D=SOME_ARRAY_VALUE&filters%5Bcreated_by_id%5D=SOME_ARRAY_VALUE&filters%5Bcreated_at%5D=SOME_STRING_VALUE&filters%5Bupdated_at%5D=SOME_STRING_VALUE&filters%5Bdocument_type%5D=SOME_STRING_VALUE&filters%5Bfile_type%5D=pdf&filters%5Bfile_type%5D=txt&filters%5Bis_in_recycle_bin%5D=SOME_BOOLEAN_VALUE&filters%5Bsearch%5D=SOME_STRING_VALUE&filters%5Bfolder_id%5D=26&filters%5Bprivate%5D=SOME_BOOLEAN_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

